def solve(a):
    H=len(a); W=len(a[0])
    o=[(r,c) for r in range(H) for c in range(W) if a[r][c]==1][0]
    t=[(r,c) for r in range(H) for c in range(W) if a[r][c]==2][0]
    b=[row[:] for row in a]
    dr = 1 if t[0]>o[0] else -1
    dc = 1 if t[1]>o[1] else -1
    r,c=o
    while True:
        nr,nc=r+dr,c+dc
        if not(0<=nr<H and 0<=nc<W) or abs(nr-t[0])==1 and abs(nc-t[1])==1 or (nr,nc)==t: break
        r,c=nr,nc
        b[r][c]=3
    def can(d):
        rr,rc_=r+d[0],c+d[1]
        if not(0<=rr<H and 0<=rc_<W): return False
        return rr!=t[0] and rc_!=t[1] and abs(rr-t[0])>=1 and abs(rc_-t[1])>=1
    hdirs=[]
    if t[1]>c: hdirs.append((0,1))
    if t[1]<c: hdirs.append((0,-1))
    vdirs=[]
    if t[0]>r: vdirs.append((1,0))
    else: vdirs.append((-1,0))
    cand=[d for d in hdirs+vdirs if can(d)]
    best=None
    for d in cand:
        n=0; rr,cc2=r+d[0],c+d[1]
        while 0<=rr<H and 0<=cc2<W and rr!=t[0] and cc2!=t[1]:
            n+=1; rr+=d[0]; cc2+=d[1]
        if best is None or n>best[0]: best=(n,d)
    _,dd=best
    while True:
        nr,nc=r+dd[0],c+dd[1]
        if not(0<=nr<H and 0<=nc<W) or nr==t[0] or nc==t[1]: break
        r,c=nr,nc
        b[r][c]=3
    return b

